package com.aabhix.camera;
import android.app.*;import android.content.*;import android.net.Uri;import com.aabhix.camera.domain.PortableConfig;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.function.Consumer;
public final class ConfigLibrary {
    private final CameraController camera;private final Activity activity;private final Consumer<PortableConfig> apply;private final File directory;
    public ConfigLibrary(Activity activity,Consumer<PortableConfig> apply,CameraController camera){this.camera=camera;this.activity=activity;this.apply=apply;directory=new File(activity.getFilesDir(),"configurations");directory.mkdirs();}
    public void show(){new Thread(()->{
        File[] files=directory.listFiles((d,name)->name.endsWith(".xml"));if(files==null)files=new File[0];Arrays.sort(files,Comparator.comparing(File::getName));
        List<String> titles=new ArrayList<>();for(File file:files){try{titles.add(new String(java.nio.file.Files.readAllBytes(new File(file.getPath()+".title").toPath()),StandardCharsets.UTF_8));}catch(Exception e){titles.add(file.getName());}}
        File[] chosen=files;activity.runOnUiThread(()->{if(activity.isFinishing()||activity.isDestroyed())return;SettingsSheet sheet=new SettingsSheet(activity,"Configurations");
            sheet.action("Library","Import XML configuration","Add GCam/LMC or Aabhix profiles; review supported values before applying",()->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);activity.startActivityForResult(intent,31);});
            sheet.action("Library","Save current setup","Remember camera controls, look, intensity, frames and original-copy preference",this::saveCurrent);
            sheet.action("Activity","Last applied configuration", "See which settings changed",()->new AlertDialog.Builder(activity).setTitle("Last applied configuration").setMessage(activity.getSharedPreferences("settings",0).getString("lastConfigReport","No configuration applied yet.")).setPositiveButton("Close",null).show());
            String[] labels={"Natural auto","Soft tones","Cinema frame","Monochrome"},styles={"original","silk","copper","silver"};
            for(int i=0;i<labels.length;i++){final int index=i;sheet.action("Ready to use",labels[i],"Auto exposure · "+styles[i]+(i==2?" · 2.39:1 frame":" · no frame"),()->{try{review(PortableConfig.parse("<aabhix-config><string name='aabhix.iso'>auto</string><int name='aabhix.wb' value='1'/><int name='aabhix.evSteps' value='0'/><string name='aabhix.styleId'>"+styles[index]+"</string><string name='aabhix.styleIntensity'>1</string><string name='aabhix.photoFrame'>"+(index==2?"cinema239":"none")+"</string><string name='aabhix.videoFrame'>"+(index==2?"cinema239":"none")+"</string></aabhix-config>"));}catch(Exception e){error(e);}});}
            for(int i=0;i<chosen.length;i++){final File file=chosen[i];sheet.action("Saved profiles",titles.get(i),"Review mapped values and compatibility",()->readFile(file));}sheet.show();});
        },"AabhixConfigLibrary").start();}
    public void importUri(Uri uri){importUris(Collections.singletonList(uri));}
    public void importUris(List<Uri> uris){
        if(uris.isEmpty()||uris.size()>100){error(new IOException("Choose 1 to 100 XML files at a time"));return;}
        new Thread(()->{int imported=0;List<String> failures=new ArrayList<>();PortableConfig only=null;
            for(Uri uri:uris){try(InputStream input=activity.getContentResolver().openInputStream(uri)){
                if(input==null)throw new IOException("File unavailable");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] chunk=new byte[8192];int n;
                while((n=input.read(chunk))!=-1){if(bytes.size()+n>2_000_000)throw new IOException("Config exceeds 2 MB");bytes.write(chunk,0,n);}
                String xml=bytes.toString(StandardCharsets.UTF_8.name());PortableConfig config=PortableConfig.parse(xml);String title="Imported XML";
                try(android.database.Cursor cursor=activity.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst()&&cursor.getString(0)!=null)title=cursor.getString(0);}
                store(title,xml);only=config;imported++;
            }catch(Exception e){failures.add(e.getMessage()==null?"File could not be imported":e.getMessage());}}
            final int count=imported;final PortableConfig selected=only;
            activity.runOnUiThread(()->{if(activity.isFinishing()||activity.isDestroyed())return;
                if(uris.size()==1&&selected!=null){review(selected);return;}
                new AlertDialog.Builder(activity).setTitle("Configuration import").setMessage(count+" saved · "+failures.size()+" rejected"+(failures.isEmpty()?"":"\n\n"+String.join("\n",failures)))
                    .setPositiveButton("Open library",(d,i)->show()).setNegativeButton("Close",null).show();});
        },"AabhixConfigImport").start();
    }
    private void readFile(File file){new Thread(()->{try{PortableConfig config=PortableConfig.parse(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));activity.runOnUiThread(()->review(config));}catch(Exception e){error(e);}},"AabhixConfigRead").start();}
    private void review(PortableConfig config){review(config,0);} private void review(PortableConfig config,int attempt){if(activity.isFinishing()||activity.isDestroyed())return;if(!activity.hasWindowFocus()){if(attempt<15)activity.getWindow().getDecorView().postDelayed(()->review(config,attempt+1),200);return;}AlertDialog.Builder dialog=new AlertDialog.Builder(activity).setTitle("Review mapped configuration").setMessage(config.summary()).setNegativeButton("Close",null);if(!config.values.isEmpty())dialog.setPositiveButton("Apply mapped values",(d,i)->apply.accept(config));dialog.show();}
    public void store(String title,String xml)throws Exception{PortableConfig.parse(xml);byte[] digest=MessageDigest.getInstance("SHA-256").digest(xml.getBytes(StandardCharsets.UTF_8));StringBuilder id=new StringBuilder();for(byte value:digest)id.append(String.format(Locale.ROOT,"%02x",value&255));File file=new File(directory,id+".xml");try(OutputStream out=new FileOutputStream(file)){out.write(xml.getBytes(StandardCharsets.UTF_8));}try(OutputStream out=new FileOutputStream(new File(file.getPath()+".title"))){out.write(title.substring(0,Math.min(120,title.length())).getBytes(StandardCharsets.UTF_8));}}
    private void saveCurrent(){try{android.content.SharedPreferences prefs=activity.getSharedPreferences("settings",0);StringBuilder xml=new StringBuilder("<aabhix-config>");for(String key:new String[]{"grid","stableVideo","stabilization","original"})xml.append("<boolean name='aabhix.").append(key).append("' value='").append(prefs.getBoolean(key,!key.equals("grid"))).append("'/>");xml.append("<int name='aabhix.jpegQuality' value='").append(prefs.getInt("jpegQuality",96)).append("'/>");for(String key:new String[]{"photoFrame","videoFrame"}){String frame=prefs.getString(key,"none");if(!Arrays.asList("none","cinema239","cinema235","cinema185","white","black").contains(frame))frame="none";xml.append("<string name='aabhix.").append(key).append("'>").append(frame).append("</string>");}xml.append("<int name='aabhix.iso' value='").append(camera.manualIso()).append("'/><string name='aabhix.exposureNs'>").append(camera.manualExposure()).append("</string><int name='aabhix.wb' value='").append(camera.whiteBalance()).append("'/><int name='aabhix.evSteps' value='").append(camera.manualIso()>0?0:camera.currentEv()).append("'/>");String style=prefs.getString("selected","original");if(style.matches("[A-Za-z0-9_.-]{1,160}"))xml.append("<string name='aabhix.styleId'>").append(style).append("</string>");xml.append("<string name='aabhix.styleIntensity'>").append(prefs.getFloat("intensity",1f)).append("</string></aabhix-config>");String snapshot=xml.toString();new Thread(()->{try{store("Aabhix setup "+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT).format(new Date()),snapshot);show();}catch(Exception e){error(e);}},"AabhixConfigSave").start();}catch(Exception e){error(e);}}
    private void error(Exception error){activity.runOnUiThread(()->error(error,0));}
    private void error(Exception error,int attempt){if(activity.isFinishing()||activity.isDestroyed())return;if(!activity.hasWindowFocus()){if(attempt<15)activity.getWindow().getDecorView().postDelayed(()->error(error,attempt+1),200);return;}new AlertDialog.Builder(activity).setTitle("Configuration not applied").setMessage(error.getMessage()).setPositiveButton("Close",null).show();}
}
